internal.body:
if (modeIndex < 0 || modeIndex > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("modeIndex valide");
}
switch (modeIndex) {
  case 0: return 0.0;
  case 1: return 8.0;
  case 2: return 10.0;
  case 3: return 12.0;
  default: return 0.0;
}

fr.sorbonne_u.components.hem2025e1.equipement.Wifi.BoxWifiImplementationI wifi = getBoxWifiOffering();
switch (modeIndex) {
  case 0:
    wifi.turnOff();
    break;
  case 1:
    wifi.turnOn();
    wifi.deactivateWifi();
    break;
  case 2:
    wifi.turnOn();
    wifi.activateWifi();
    break;
  case 3:
    wifi.turnOn();
    wifi.activateWifi();
    break;
}
currentMode = modeIndex;

upMode.body:
if (suspended()) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("!suspended()");
}
if (currentMode >= MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("currentMode < MAX_MODE");
}
if (currentMode < MAX_MODE) {
  currentMode++;
  applyMode(currentMode);
  return true;
}
return false;

downMode.body:
if (suspended()) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("!suspended()");
}
if (currentMode <= 0) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("currentMode > 0");
}
if (currentMode > 0) {
  currentMode--;
  applyMode(currentMode);
  return true;
}
return false;

setMode.body:
if (suspended()) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("!suspended()");
}
if (modeIndex < 0 || modeIndex > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("modeIndex valide");
}
if (modeIndex >= 0 && modeIndex <= MAX_MODE) {
  currentMode = modeIndex;
  applyMode(currentMode);
  return true;
}
return false;

getModeConsumption.body:
if (modeIndex < 0 || modeIndex > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("modeIndex valide");
}
return computePowerLevel(modeIndex);

suspend.body:
if (suspended()) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("!suspended()");
}
getBoxWifiOffering().turnOff();
isSuspended = true;
return true;

resume.body:
if (!suspended()) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("suspended()");
}
applyMode(currentMode);
isSuspended = false;
return true;

emergency.body:
switch (currentMode) {
  case 0: return 0.0;
  case 1: return 0.3;
  case 2: return 0.5;
  case 3: return 0.8;
  default: return 0.0;
}
